def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    # The seed object is the 3x3 region at rows 0-2, columns 1-3.
    # Each 0 marker stamps this motif centered at its own position.
    motif = [row[1:4] for row in grid[:3]]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                for dr in range(3):
                    for dc in range(3):
                        rr, cc = r + dr - 1, c + dc - 1
                        value = motif[dr][dc]
                        if value != bg and 0 <= rr < h and 0 <= cc < w:
                            out[rr][cc] = value
    return out

